#include "rxt_private.h"
#include "dbg.h"

/*==========================================================================*/
/*      D E F I N E S  -  E N U M E R A T I O N S  -  T Y P E D E F S       */
/*==========================================================================*/

#define string "\r\n" "rxt "

/*==========================================================================*/
/*                  F U N C T I O N   P R O T O T Y P E S                   */
/*==========================================================================*/

/*==========================================================================*/
/*                            V A R I A B L E S                             */
/*==========================================================================*/

/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/

void rxt_oem_start (void)
{


	if (rxt.ready.byte == 0xFF)
	{
		#if DBG_RXT == 1
		  dbg_tx_text (string) ;
		  dbg_tx_text ("oem start") ;
		#endif
		if(rxt.state == RXT_STATE_STARTED)
		{		
			rxt_extend_runtime_update () ;
			if(rxt.ready.byte != 0xFF)
			{		
				return ; // don't update max extend runtime reached	
			}
			
		}
		else
		{
			rxt.state = RXT_STATE_STARTING ;
			rxt.oem_start = TRUE ;
		}
		rxt.runtime = rxt.default_runtime ;
		rxt_rf_update ((rxt.ready.byte == 0xFF)?TRUE:FALSE) ;
		timeout_update (rxt.timeout, RXT_START_TIMEOUT) ;
		timeout_start (rxt.timeout) ;
	}
}

